// bun tools/pack.ts: the registry's components and the project template as strings in src/registry.gen.ts, so `raea add`
// and `raea init` work inside the shell (raea's V8 reads only the project folder, not this package). Run after
// changing anything under registry/ or template/; `bun test` fails when the generated file is stale.
import { readdirSync, readFileSync, writeFileSync } from "fs";
import { join } from "path";

const here = join(import.meta.dir, "..");
const read = (dir: string) =>
  Object.fromEntries(readdirSync(join(here, dir)).filter((f) => !f.startsWith(".")).sort().map((f) => [f, readFileSync(join(here, dir, f), "utf8")]));

export function generated(): string {
  const registry = read("registry");
  const template = read("template");
  return `// generated by tools/pack.ts from registry/ and template/: don't edit, run \`bun tools/pack.ts\`\nexport const REGISTRY: Record<string, string> = ${JSON.stringify(registry, null, 2)};\nexport const TEMPLATE: Record<string, string> = ${JSON.stringify(template, null, 2)};\n`;
}

if (import.meta.main) writeFileSync(join(here, "src/registry.gen.ts"), generated());
